fn decode_mortlach_multi4_select_int(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xff23e063 != 0xc1218000 {
        return Err(DecodeError::Unallocated);
    }
    // 1|10|0000|1|size=xx|1|Zm=xxx|01|100|PNv=xxx|Zn=xxx|00|Zd=xxx|00
    // SEL  { <Zd1>.<T>-<Zd4>.<T> }, <PNv>, { <Zn1>.<T>-<Zn4>.<T> }, { <Zm1>.<T>-<Zm4>.<T> }
    let size: u8 = ((bits >> 22) & 0x3) as u8;
    let Zn: u8 = ((bits >> 7) & 0x7) as u8;
    let n: u8 = Zn << 2;
    let Zm: u8 = ((bits >> 18) & 0x7) as u8;
    let m: u8 = Zm << 2;
    let Zd: u8 = ((bits >> 2) & 0x7) as u8;
    let d: u8 = Zd << 2;
    let PNv: u8 = ((bits >> 10) & 0x7) as u8;
    let v: u8 = 0b1000 | PNv;
    Ok(Instruction::SelMzPZz4 {
        Zd1: ZReg::new(d),
        T: match size {
            0b00 => Arrangement::element(ElementWidth::B),
            0b01 => Arrangement::element(ElementWidth::H),
            0b10 => Arrangement::element(ElementWidth::S),
            _ => Arrangement::element(ElementWidth::D),
        },
        Zd4: ZReg::new((d + 3) % 32),
        PNv: PNReg::new(v),
        Zn1: ZReg::new(n),
        Zn4: ZReg::new((n + 3) % 32),
        Zm1: ZReg::new(m),
        Zm4: ZReg::new((m + 3) % 32),
    })
}

